<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Review extends Model {protected $fillable=['user_id','product_id','order_item_id','rating','title','content','status','verified_purchase','moderation_note','moderated_by','moderated_at'];protected function casts():array{return ['rating'=>'integer','verified_purchase'=>'boolean','moderated_at'=>'datetime'];}public function user(){return $this->belongsTo(User::class);}public function product(){return $this->belongsTo(Product::class);}public function orderItem(){return $this->belongsTo(OrderItem::class);}public function moderator(){return $this->belongsTo(User::class,'moderated_by');}}
